fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/native-ffg")
}
fn genesis() -> CommittedState {
    let v: Value = serde_json::from_slice(&fs::read(root().join("bootstrap.json")).unwrap()).unwrap();
    fixture::genesis(
        &v["public_keys"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| hex::decode(v.as_str().unwrap()).unwrap())
            .collect::<Vec<_>>(),
    )
}
fn trust() -> NativeGenesisTrustV1 {
    NativeGenesisTrustV1 {
        settlement_policy: fixture::policy(),
        // Fixed independently of the submitted chain; retained fixture provenance.
        state_root: fixture::hash("43a0e6842cfa5c194879cb344ce5ad99b2814c31b52a0cc9d81d374e18be4184"),
    }
}
fn blocks(mode: &str) -> Vec<NativeReplayBlockV1> {
    let v: Vec<Value> = serde_json::from_slice(&fs::read(root().join(format!("{mode}.json"))).unwrap()).unwrap();
    v.iter().map(fixture::decode_block).collect()
}

#[test]
fn genuine_native_quorums_require_both_ffg_rounds_and_finalize_the_exact_settlement() {
    let genesis = genesis();
    assert_eq!(genesis.state_root(), trust().state_root.0);
    let bootstrap: Value = serde_json::from_slice(&fs::read(root().join("bootstrap.json")).unwrap()).unwrap();
    assert_eq!(
        bootstrap["genesis_state_root"].as_str(),
        Some(hex::encode(trust().state_root).as_str())
    );
    for mode in ["full", "two"] {
        let blocks = blocks(mode);
        let native = verify_native_finality(&genesis, trust(), &blocks, NativeReplayLimitsV1::default()).unwrap();
        assert_eq!(native.report().finalized_epoch, 1);
        assert_eq!(
            native.report().finalized.block.0,
            *blocks[1].envelope.header.id().as_bytes()
        );
        assert_eq!(native.report().finalized.slot, 2);
        assert_eq!(native.report().replayed_slot, 96);
        assert!(matches!(
            verify_native_finality(&genesis, trust(), &blocks[..5], NativeReplayLimitsV1::default()),
            Err(NativeFinalityErrorV1::NotFinalized)
        ));
    }
}

#[test]
fn insufficient_duplicate_and_conflicting_real_votes_do_not_finalize() {
    for mode in ["insufficient", "duplicates", "conflict"] {
        assert!(
            matches!(
                verify_native_finality(&genesis(), trust(), &blocks(mode), NativeReplayLimitsV1::default()),
                Err(NativeFinalityErrorV1::NotFinalized)
            ),
            "{mode}"
        );
    }
}

#[test]
fn corrupt_proposer_attester_proof_body_and_foreign_branch_are_rejected() {
    let genesis = genesis();
    let original = blocks("full");
    for end in [false, true] {
        let mut b = original.clone();
        let sig = &mut b[0].envelope.proposer_sig;
        let at = if end { sig.len() - 1 } else { 0 };
        sig[at] ^= 1;
        assert!(matches!(
            verify_native_finality(&genesis, trust(), &b, NativeReplayLimitsV1::default()),
            Err(NativeFinalityErrorV1::Transition { block: 0, .. })
        ));
    }
    let mut b = original.clone();
    b[3].attestations[0].signature[0] ^= 1;
    assert!(verify_native_finality(&genesis, trust(), &b, NativeReplayLimitsV1::default()).is_err());
    let mut b = original.clone();
    *b[1].transactions[0].last_mut().unwrap() ^= 1;
    assert!(verify_native_finality(&genesis, trust(), &b, NativeReplayLimitsV1::default()).is_err());
    let mut b = original.clone();
    // An unsigned retarget is refused by the native transition (the vote
    // signature covers the target). Validly signed foreign votes are covered
    // by tests/ffg_foreign_vote.rs.
    b[3].attestations[0].data.target_root = [9; 32];
    assert!(matches!(
        verify_native_finality(&genesis, trust(), &b, NativeReplayLimitsV1::default()),
        Err(NativeFinalityErrorV1::Transition { block: 3, .. })
    ));
    let mut b = original;
    b.remove(0);
    assert!(matches!(
        verify_native_finality(&genesis, trust(), &b, NativeReplayLimitsV1::default()),
        Err(NativeFinalityErrorV1::Ancestry)
    ));
}

#[test]
fn independent_genesis_and_all_replay_budgets_fail_before_signature_work() {
    let genesis = genesis();
    let mut b = blocks("full");
    b[0].envelope.proposer_sig.fill(0);
    let mut wrong = trust();
    wrong.state_root = B256::repeat_byte(9);
    assert!(matches!(
        verify_native_finality(&genesis, wrong, &b, NativeReplayLimitsV1::default()),
        Err(NativeFinalityErrorV1::Trust)
    ));
    let normal = NativeReplayLimitsV1::default();
    for limit in [
        NativeReplayLimitsV1 { blocks: 1, ..normal },
        NativeReplayLimitsV1 { epochs: 2, ..normal },
        NativeReplayLimitsV1 {
            attestations: 1,
            ..normal
        },
        NativeReplayLimitsV1 {
            transactions: 0,
            ..normal
        },
        NativeReplayLimitsV1 { proofs: 0, ..normal },
        NativeReplayLimitsV1 { bytes: 304, ..normal },
        NativeReplayLimitsV1 {
            blocks: 10_001,
            ..normal
        },
    ] {
        assert!(matches!(
            verify_native_finality(&genesis, trust(), &b, limit),
            Err(NativeFinalityErrorV1::Limit)
        ));
    }
}

fn keys() -> &'static Vec<(Vec<u8>, Vec<u8>)> {
    static KEYS: OnceLock<Vec<(Vec<u8>, Vec<u8>)>> = OnceLock::new();
    KEYS.get_or_init(|| (0..3).map(|_| bloch_crypto::crypto::generate_keypair()).collect())
}
fn cp_policy() -> CheckpointPolicy {
    CheckpointPolicy::new(
        0x91,
        fixture::policy().genesis.0,
        SignerSet {
            id: 1,
            adopted_epoch: 0,
            threshold: 2,
            min_external: 1,
            signers: keys()
                .iter()
                .enumerate()
                .map(|(i, k)| Signer {
                    pubkey: k.0[4..].try_into().unwrap(),
                    external: i == 2,
                })
                .collect(),
        },
        Phase::A,
    )
    .unwrap()
}
fn spec() -> Arc<BlochChainSpec> {
    Arc::new(BlochChainSpec::new(ChainSpec::testnet(), B256::repeat_byte(0xd3), 0).unwrap())
}
fn open(path: &Path) -> BlochProviderFactory {
    ProviderFactory::new(
        Arc::new(init_db_for::<_, BlochTables>(path.join("db"), DatabaseArguments::test()).unwrap()),
        spec(),
        StaticFileProvider::read_write(path.join("static")).unwrap(),
        RocksDBBuilder::new(path.join("rocks"))
            .with_default_tables()
            .build()
            .unwrap(),
        reth_tasks::Runtime::test(),
    )
    .unwrap()
}
/// The statement of the genuine native settlement (block 1, slot 2), decoded
/// with the native codec of the pinned consensus.
fn native_statement(bytes: &[u8]) -> SettlementStatementV2 {
    let tx = bloch_pos_committee::l2_settlement::Transaction::decode(bytes).unwrap();
    SettlementStatementV2::decode(&tx.statement).unwrap()
}
fn no_numeric_finality(source: &BlochProviderFactory) {
    let reader = source.database_provider_ro().unwrap();
    for key in [ChainStateKey::LastSafeBlock, ChainStateKey::LastFinalizedBlock] {
        assert_eq!(reader.tx_ref().get::<ChainState>(key).unwrap(), None);
    }
}
/// Canonical L2 block 1 executed by Reth, anchored at the native source block
/// named by the genuine settlement statement.
fn canonical_l2(path: &Path) -> ReplayFloor {
    let b = blocks("full");
    let statement = native_statement(&b[1].transactions[0]);
    let source = open(path);
    let prepared = prepare_genesis(&spec(), source.latest().unwrap().as_ref()).unwrap();
    let writer = source.database_provider_rw().unwrap();
    writer.save_blocks(vec![prepared], SaveBlocksMode::Full).unwrap();
    writer.commit().unwrap();
    let mut coordinator = CanonicalCoordinator::attach(source.clone()).unwrap();
    coordinator
        .extend(
            coordinator.head().hash(),
            BlochNextBlockEnvCtx {
                timestamp: 1,
                prevrandao: B256::repeat_byte(7),
                anchor_root: statement.l1_block,
                deposits: vec![],
            },
            vec![],
        )
        .unwrap();
    let block = source.block_by_number(1).unwrap().unwrap();
    assert_eq!(block.header.0.hash(), statement.l2_header_hash);
    ReplayFloor {
        number: 1,
        hash: source.sealed_header(1).unwrap().unwrap().hash(),
    }
}
/// Canonical L2 plus the legacy WS-checkpoint stores, with a genuinely signed
/// WS checkpoint over a genuine native header. The settlement store stays
/// empty: its admission accepts only the historical 0x0E native envelope.
struct Disk {
    root: tempfile::TempDir,
    checkpoints: PathBuf,
    settlements: PathBuf,
    cp: CheckpointMark,
    settlement: SettlementStoreMarkV1,
    l2: ReplayFloor,
    legacy_admission_refused: bool,
}
impl Disk {
    fn new(checkpoint_index: usize, epoch: u64) -> Self {
        let b = blocks("full");
        let transaction = &b[1].transactions[0];
        let statement = native_statement(transaction);
        let root = tempfile::tempdir().unwrap();
        let l2 = canonical_l2(root.path());
        let header = b[checkpoint_index].envelope.header;
        let checkpoint = WeakSubjectivityCheckpoint {
            version: ws::WS_FORMAT_VERSION,
            network_id: 0x91,
            genesis_root: fixture::policy().genesis.0,
            epoch,
            block_root: *header.id().as_bytes(),
            state_root: header.state_root,
            validator_set_root: [12; 32],
            issued_at: 3,
            signer_set_id: 1,
        };
        let envelope = CheckpointEnvelope {
            checkpoint,
            signatures: keys()
                .iter()
                .enumerate()
                .map(|(i, k)| {
                    let signature = bloch_crypto::crypto::sign(&k.1, &checkpoint.ws_digest()).unwrap();
                    (i as u8, signature[4..].to_vec())
                })
                .collect(),
        };
        let checkpoints = root.path().join("checkpoints");
        let settlements = root.path().join("settlements");
        let mut cp = CheckpointStore::create(&checkpoints, cp_policy()).unwrap();
        cp.accept(&envelope, &header.canonical_serialize(), 3).unwrap();
        let verified = cp.current(3).unwrap();
        let expected = SettlementAdmissionExpectationV1 {
            settlement: SettlementExpectationV1 {
                statement,
                source_predecessor: B256::ZERO,
            },
            block: B256::from(*b[1].envelope.header.id().as_bytes()),
            slot: 2,
            checkpoint: verified.anchor(),
            transaction_index: 0,
        };
        // Exact-byte inclusion of the genuine native settlement under the
        // genuine WS anchor. Ancestry and body authenticate; the legacy
        // settlement codec then refuses the current native wire tag.
        let evidence = TransactionInclusionEvidenceV1::new(
            verified.anchor(),
            b[1..=checkpoint_index]
                .iter()
                .map(|b| Bytes::copy_from_slice(&b.envelope.header.canonical_serialize()))
                .collect(),
            vec![Bytes::copy_from_slice(transaction)],
        )
        .unwrap();
        let legacy_admission_refused = matches!(
            bind_settlement_checkpoint_authority(verified, evidence, &expected),
            Err(SettlementAuthorityErrorV1::Admission(
                SettlementAdmissionErrorV1::Codec(_)
            ))
        );
        let store = SettlementStoreV1::create(&settlements, fixture::policy()).unwrap();
        Self {
            root,
            checkpoints,
            settlements,
            cp: cp.mark().unwrap(),
            settlement: store.mark(),
            l2,
            legacy_admission_refused,
        }
    }
    fn request(&self) -> SettlementRecoveryRequestV1<'_> {
        SettlementRecoveryRequestV1 {
            checkpoint_path: &self.checkpoints,
            checkpoint_policy: cp_policy(),
            checkpoint_floor: self.cp,
            settlement_path: &self.settlements,
            settlement_policy: fixture::policy(),
            settlement_floor: self.settlement,
            l2_floor: self.l2,
            current_epoch: 3,
            maximum_proofs: 1,
            canonical_limits: ReplayLimits::default(),
        }
    }
    fn history(&self) -> Vec<(PathBuf, Vec<u8>)> {
        let mut files = [&self.checkpoints, &self.settlements]
            .into_iter()
            .flat_map(|p| fs::read_dir(p).unwrap().map(|e| e.unwrap().path()))
            .collect::<Vec<_>>();
        files.sort();
        files
            .into_iter()
            .map(|p| {
                let b = fs::read(&p).unwrap();
                (p, b)
            })
            .collect()
    }
}

#[test]
fn native_ffg_finalizes_the_exact_settlement_bytes_and_replay_is_restart_stable() {
    let b = blocks("full");
    let settlement = b[1].transactions[0].clone();
    // Current native wire set: synchronous settlement tag 0x12.
    assert_eq!(settlement[0], WIRE_TAG);
    let first = verify_native_finality(&genesis(), trust(), &b, NativeReplayLimitsV1::default()).unwrap();
    let expected = vec![(2, B256::from(*b[1].envelope.header.id().as_bytes()), settlement.clone())];
    // A restart replays from the pinned genesis again; nothing is carried over.
    for _ in 0..2 {
        let again =
            verify_native_finality(&genesis(), trust(), &blocks("full"), NativeReplayLimitsV1::default()).unwrap();
        assert_eq!(again.report(), first.report());
        let finalized = again
            .finalized_settlements()
            .map(|(slot, id, bytes)| (slot, id, bytes.to_vec()))
            .collect::<Vec<_>>();
        assert_eq!(finalized, expected);
    }
    // The 2/3 chain finalizes the same settlement bytes.
    let two = verify_native_finality(&genesis(), trust(), &blocks("two"), NativeReplayLimitsV1::default()).unwrap();
    assert_eq!(
        two.finalized_settlements()
            .map(|(slot, id, bytes)| (slot, id, bytes.to_vec()))
            .collect::<Vec<_>>(),
        expected
    );
    // The legacy 0x0E envelope codec of the WS-checkpoint store does not
    // decode the current native settlement.
    assert!(SettlementTransactionV1::decode_wire(&settlement).is_err());
}

#[test]
fn genuine_ws_checkpoints_cannot_admit_or_stand_in_for_native_ffg() {
    let native = verify_native_finality(&genesis(), trust(), &blocks("full"), NativeReplayLimitsV1::default()).unwrap();
    assert_eq!(native.report().finalized_epoch, 1);
    // (1, 1) is the natively finalized epoch-1 checkpoint, (1, 0) a stale epoch
    // claim and (3, 2) the correct epoch-2 root (slot 63), which is not finalized.
    for (position, epoch) in [(1, 0), (1, 1), (3, 2)] {
        let disk = Disk::new(position, epoch);
        assert!(disk.legacy_admission_refused, "({position}, {epoch})");
        let source = open(disk.root.path());
        let before = disk.history();
        assert!(recover_canonical_ffg_settlements(&source, disk.request(), &native).is_err());
        assert!(recover_and_stage_ffg_finality_candidate(&source, disk.request(), &native, None).is_err());
        // The WS-only compatibility path has no settlement to stage either.
        assert!(recover_and_stage_native_finality_candidate(&source, disk.request(), None).is_err());
        assert_eq!(disk.history(), before);
        no_numeric_finality(&source);
    }
}

#[test]
fn ffg_recovery_refuses_future_native_replay_and_foreign_policy_before_store_access() {
    let disk = Disk::new(1, 1);
    let source = open(disk.root.path());
    let before = disk.history();
    let native = verify_native_finality(&genesis(), trust(), &blocks("full"), NativeReplayLimitsV1::default()).unwrap();
    // Replayed tip is slot 96 (epoch 3): an observation at epoch 2 is refused
    // by the native-finality binding itself.
    let mut early = disk.request();
    early.current_epoch = 2;
    assert!(matches!(
        recover_canonical_ffg_settlements(&source, early, &native),
        Err(SettlementRecoveryErrorV1::NativeFinality(NativeFinalityErrorV1::Trust))
    ));
    let mut early = disk.request();
    early.current_epoch = 2;
    assert!(matches!(
        recover_and_stage_ffg_finality_candidate(&source, early, &native, None),
        Err(FinalityCandidateErrorV1::Recovery(
            SettlementRecoveryErrorV1::NativeFinality(NativeFinalityErrorV1::Trust)
        ))
    ));
    let mut foreign = disk.request();
    foreign.settlement_policy.network = B256::repeat_byte(0xa1);
    assert!(matches!(
        recover_canonical_ffg_settlements(&source, foreign, &native),
        Err(SettlementRecoveryErrorV1::NativeFinality(NativeFinalityErrorV1::Trust))
    ));
    // At the trusted epoch the binding passes and the refusal comes from the
    // stores instead (no admissible settlement), not from native finality.
    let current = recover_canonical_ffg_settlements(&source, disk.request(), &native);
    assert!(current.is_err());
    assert!(!matches!(current, Err(SettlementRecoveryErrorV1::NativeFinality(_))));
    assert_eq!(disk.history(), before);
    no_numeric_finality(&source);
}

#[test]
fn asynchronous_boundary_refuses_legacy_mode_and_wrong_policy_and_counts_both_proof_tags() {
    use bloch_settlement_recovery::native::audit_finalized_async_settlements;
    let root = tempfile::tempdir().unwrap();
    let floor = canonical_l2(root.path());
    let source = open(root.path());
    let blocks = blocks("full");
    let native = verify_native_finality(&genesis(), trust(), &blocks, NativeReplayLimitsV1::default()).unwrap();
    assert!(
        audit_finalized_async_settlements(&native, &source, fixture::policy(), floor, ReplayLimits::default()).is_err()
    );
    let mut foreign = fixture::policy();
    foreign.network = B256::repeat_byte(0xa1);
    assert!(audit_finalized_async_settlements(&native, &source, foreign, floor, ReplayLimits::default()).is_err());
    for tag in [WIRE_TAG, ASYNC_WIRE_TAG] {
        let mut changed = blocks.clone();
        changed[1].transactions[0][0] = tag;
        let limits = NativeReplayLimitsV1 {
            proofs: 0,
            ..Default::default()
        };
        assert_eq!(
            verify_native_finality(&genesis(), trust(), &changed, limits).err(),
            Some(NativeFinalityErrorV1::Limit)
        );
    }
}
